    if (x.nvsram && x.nvsram.cur && x.nvsram.rec && x.nvsram.cur !== x.nvsram.rec) add('medium', 'NVSRAM behind recommended', `${x.nvsram.cur} -> ${x.nvsram.rec} recommended.`);
